import{_ as a,o as e,a as _,b as c}from"./app.B47EjQll.js";const b=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C API","link":"/api/api_list"},{"text":"SIMD API","link":"/api/SIMD-API/SIMD-API"},{"text":"C API","link":"/api/SIMD-API/c_api/README"},{"text":"矩阵计算搬运","link":"/api/SIMD-API/c_api/cube_datamove/cube_datamove"},{"text":"概述","link":"/api/SIMD-API/c_api/cube_datamove/overview"}]},"headers":[],"relativePath":"api/SIMD-API/c_api/cube_datamove/overview.md","filePath":"api/SIMD-API/c_api/cube_datamove/overview.md","outlineHeaders":[{"level":2,"title":"API列表","slug":"API列表","link":"#API列表"},{"level":3,"title":"矩阵计算的搬入","slug":"矩阵计算的搬入","link":"#矩阵计算的搬入"},{"level":3,"title":"矩阵搬入辅助配置接口","slug":"矩阵搬入辅助配置接口","link":"#矩阵搬入辅助配置接口"},{"level":3,"title":"矩阵计算的搬出","slug":"矩阵计算的搬出","link":"#矩阵计算的搬出"},{"level":3,"title":"矩阵搬出辅助配置接口","slug":"矩阵搬出辅助配置接口","link":"#矩阵搬出辅助配置接口"}],"lastUpdated":1794017913000}'),d={name:"api/SIMD-API/c_api/cube_datamove/overview.md"};function o(r,t,l,u,m,p){return e(),_("div",null,[...t[0]||(t[0]=[c('<div><article class="markdown-body"><h1>概述</h1><h2 id="API列表">API列表<a class="header-anchor" href="#API列表">​</a></h2><h3 id="矩阵计算的搬入">矩阵计算的搬入<a class="header-anchor" href="#矩阵计算的搬入">​</a></h3><p><strong>表1</strong> 矩阵计算的搬入接口</p><table><thead><tr><th>接口名称</th><th>接口描述</th><th>最细粒度公共头文件</th></tr></thead><tbody><tr><td><a href="cube_compute_load/asc_copy_gm2l1.html">asc_copy_gm2l1</a></td><td>将GM中的数据搬运到L1中。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_gm2l1_arch_2201.html">asc_copy_gm2l1（NPU架构版本2201）</a></td><td>将矩阵数据从Global Memory搬运到L1 Buffer中，并支持不同类型的pad模式。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_gm2l1_highdim_split_arch_3510.html">asc_copy_gm2l1（NPU架构版本3510，高维切分数据搬运）</a></td><td>将GM数据按高维切分方式搬运到L1 Buffer，支持按通道插入或移除Padding。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_gm2l1_2d_arch_3510.html">asc_copy_gm2l1（NPU架构版本3510，2D矩阵搬运模式）</a></td><td>以512字节分形为单位，将GM中的2D矩阵数据切分搬运到L1 Buffer，搬运过程中不进行分形格式转换。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_gm2l1_align.html">asc_copy_gm2l1_align</a></td><td>将GM中的数据padding后搬运到L1中。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_gm2l1_dn2nz.html">asc_copy_gm2l1_dn2nz</a></td><td>将GM中的数据搬运到L1中，在此过程中执行DN-&gt;NZ/NCHW-&gt;NC1HWC0/NCHW-&gt;C1HWNC0操作。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_gm2l1_nd2nz.html">asc_copy_gm2l1_nd2nz</a></td><td>将GM数据搬运到L1 Buffer，并将ND格式转换为Nz分形格式。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_gm2l1_nd2nz_arch_2201.html">asc_copy_gm2l1_nd2nz（NPU架构版本2201）</a></td><td>将GM数据搬运到L1 Buffer，支持ND格式到NZ格式的转换。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_gm2l1_nd2nz_arch_3510.html">asc_copy_gm2l1_nd2nz（NPU架构版本3510）</a></td><td>将GM中的ND格式数据搬运到L1 Buffer，并转换为Nz分形排布。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_gm2l0a.html">asc_copy_gm2l0a</a></td><td>将GM中的数据搬运到L0A中。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_gm2l0b.html">asc_copy_gm2l0b</a></td><td>将GM中的数据搬运到L0B中。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12l0a.html">asc_copy_l12l0a</a></td><td>用于搬运存放在L1 Buffer里的512B大小的矩阵到L0A Buffer里。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12l0a_arch_2201.html">asc_copy_l12l0a（NPU架构版本2201）</a></td><td>用于搬运存放在L1 Buffer里的512B大小的矩阵到L0A Buffer里。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12l0a_2d_arch_3510.html">asc_copy_l12l0a（NPU架构版本3510，2D矩阵搬运）</a></td><td>以512字节分形为单位，将L1 Buffer中的2D矩阵搬运到L0A Buffer，支持非转置和转置搬运。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12l0a_3d_arch_3510.html">asc_copy_l12l0a（NPU架构版本3510，3D矩阵搬运）</a></td><td>将L1 Buffer中的Feature Map执行img2col展开后搬运到L0A Buffer，也支持2D矩阵数据搬运。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12l0b.html">asc_copy_l12l0b</a></td><td>用于搬运存放在L1 Buffer里的512B大小的矩阵到L0B Buffer里。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12l0b_arch_2201.html">asc_copy_l12l0b（NPU架构版本2201）</a></td><td>用于搬运存放在L1 Buffer里的512B大小的矩阵到L0B Buffer里。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12l0b_2d_arch_3510.html">asc_copy_l12l0b（NPU架构版本3510，2D矩阵搬运）</a></td><td>以512字节分形为单位，将L1 Buffer中的2D矩阵搬运到L0B Buffer，支持非转置和转置搬运。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12l0b_3d_arch_3510.html">asc_copy_l12l0b（NPU架构版本3510，3D矩阵搬运）</a></td><td>将L1 Buffer中的Feature Map执行img2col展开后搬运到L0B Buffer，也支持2D矩阵数据搬运。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12l0a_mx.html">asc_copy_l12l0a_mx</a></td><td>将Mx scale矩阵从L1 Buffer搬运到L0A Buffer。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12l0b_mx.html">asc_copy_l12l0b_mx</a></td><td>将Mx scale矩阵从L1 Buffer搬运到L0B Buffer。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12l0a_trans.html">asc_copy_l12l0a_trans</a></td><td>该接口实现带转置的2D格式数据从L1 Buffer到L0A Buffer的加载。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12l0b_trans.html">asc_copy_l12l0b_trans</a></td><td>该接口实现带转置的2D格式数据从L1 Buffer到L0B Buffer的加载。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12l0b_trans_arch_2201.html">asc_copy_l12l0b_trans（NPU架构版本2201）</a></td><td>该接口实现带转置的2D格式数据从L1 Buffer到L0B Buffer的加载。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12l0b_trans_arch_3510.html">asc_copy_l12l0b_trans（NPU架构版本3510）</a></td><td>将数据从L1 Buffer搬运到L0B Buffer，搬运过程中以大小为512字节的数据分形为单位进行二维分形矩阵转置。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12l0b_sparse.html">asc_copy_l12l0b_sparse</a></td><td>用于搬运存放在L1 Buffer里的512B大小的稠密权重矩阵到L0B Buffer里，同时读取128B大小的索引矩阵用于稠密矩阵的稀疏化。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12l0c.html">asc_copy_l12l0c</a></td><td>将矩阵由L1 Buffer搬运到L0C Buffer中。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12bt.html">asc_copy_l12bt</a></td><td>将MMAD指令的Bias数据从L1 Buffer搬运到BiasTable Buffer中。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12bt_arch_2201.html">asc_copy_l12bt（NPU架构版本2201）</a></td><td>将数据从L1 Buffer搬运到BiasTable Buffer中，BiasTable Buffer用于存放矩阵计算中的Bias。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12bt_arch_3510.html">asc_copy_l12bt（NPU架构版本3510）</a></td><td>将L1 Buffer中的偏置数据搬运到BiasTable Buffer，支持连续和高维切分搬运，并按数据类型和配置进行转换或位宽扩展。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12fb.html">asc_copy_l12fb</a></td><td>将数据从L1 Buffer搬运到Fixpipe Buffer中，Fixpipe Buffer用于存放量化参数。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12fb_arch_2201.html">asc_copy_l12fb（NPU架构版本2201）</a></td><td>将数据从L1 Buffer搬运到Fixpipe Buffer中，Fixpipe Buffer用于存放量化参数。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_load/asc_copy_l12fb_arch_3510.html">asc_copy_l12fb（NPU架构版本3510）</a></td><td>将L1 Buffer中的量化参数和ReLU参数搬运到Fixpipe Buffer，支持连续和高维切分搬运。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr></tbody></table><h3 id="矩阵搬入辅助配置接口">矩阵搬入辅助配置接口<a class="header-anchor" href="#矩阵搬入辅助配置接口">​</a></h3><p><strong>表2</strong> 矩阵搬入辅助配置接口</p><table><thead><tr><th>接口名称</th><th>接口描述</th><th>最细粒度公共头文件</th></tr></thead><tbody><tr><td><a href="cube_load_aux_config/asc_fill_l0a.html">asc_fill_l0a</a></td><td>将L0A Buffer的Local Memory初始化为某一具体数值。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_load_aux_config/asc_fill_l0b.html">asc_fill_l0b</a></td><td>将L0B Buffer的Local Memory初始化为某一具体数值。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_load_aux_config/asc_fill_l1.html">asc_fill_l1</a></td><td>将L1 Buffer的Local Memory初始化为某一具体数值。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_load_aux_config/asc_load_image_to_cbuf.html">asc_load_image_to_cbuf</a></td><td>将图像数据从Global Memory搬运到L1 Buffer。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_load_aux_config/asc_set_gm2l1_loop1_stride.html">asc_set_gm2l1_loop1_stride</a></td><td>将数据从GM搬运到L1 Buffer时，设置内层循环中相邻迭代数据块间的间隔。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_load_aux_config/asc_set_gm2l1_loop2_stride.html">asc_set_gm2l1_loop2_stride</a></td><td>将数据从GM搬运到L1 Buffer时，设置外层循环中相邻迭代数据块间的间隔。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_load_aux_config/asc_set_gm2l1_loop_size.html">asc_set_gm2l1_loop_size</a></td><td>将数据从GM搬运到L1 Buffer时，设置数据搬运流程中的循环次数。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_load_aux_config/asc_set_gm2l1_nz_para.html">asc_set_gm2l1_nz_para</a></td><td>设置MTE2_NZ_PARA寄存器的值。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_load_aux_config/asc_set_gm2l1_pad.html">asc_set_gm2l1_pad</a></td><td>设置<a href="cube_compute_load/asc_copy_gm2l1_align.html">asc_copy_gm2l1_align</a>接口的常量填充值。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_load_aux_config/asc_set_gm2l1_padding.html">asc_set_gm2l1_padding</a></td><td>设置<a href="cube_compute_load/asc_copy_gm2l1_highdim_split_arch_3510.html">asc_copy_gm2l1（NPU架构版本3510，高维切分数据搬运）</a>的填充值。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_load_aux_config/asc_set_l12l0a_3d_padding.html">asc_set_l12l0a_3d_padding</a></td><td>设置3D左矩阵搬运填充值。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_load_aux_config/asc_set_l12l0b_3d_padding.html">asc_set_l12l0b_3d_padding</a></td><td>设置3D右矩阵搬运填充值。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_load_aux_config/asc_set_l13d_fmatrix.html">asc_set_l13d_fmatrix</a></td><td>配置3D img2col搬运模式下左矩阵的Feature Map属性描述参数。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_load_aux_config/asc_set_l13d_fmatrix_b.html">asc_set_l13d_fmatrix_b</a></td><td>配置3D img2col搬运模式下右矩阵的Feature Map属性描述参数。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_load_aux_config/asc_set_l13d_rpt.html">asc_set_l13d_rpt</a></td><td>配置3D img2col搬运模式下使用<code>repeat</code>模式搬运左矩阵所需的参数。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_load_aux_config/asc_set_l13d_rpt_b.html">asc_set_l13d_rpt_b</a></td><td>配置3D img2col搬运模式下使用<code>repeat</code>模式搬运右矩阵所需的参数。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_load_aux_config/asc_set_l13d_size.html">asc_set_l13d_size</a></td><td>设置<a href="cube_compute_load/asc_copy_l12l0a_arch_2201.html">asc_copy_l12l0a</a>/<a href="cube_compute_load/asc_copy_l12l0b_arch_2201.html">asc_copy_l12l0b</a>的3D格式搬运接口在L1 Buffer的边界值。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_load_aux_config/asc_set_l3d_rpt_b.html">asc_set_l3d_rpt_b</a></td><td>通过64位配置值设置3D img2col搬运模式下使用<code>repeat</code>模式搬运右矩阵所需的参数。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr></tbody></table><h3 id="矩阵计算的搬出">矩阵计算的搬出<a class="header-anchor" href="#矩阵计算的搬出">​</a></h3><p><strong>表3</strong> 矩阵计算的搬出接口</p><table><thead><tr><th>接口名称</th><th>接口描述</th><th>最细粒度公共头文件</th></tr></thead><tbody><tr><td><a href="cube_compute_store/asc_copy_l0c2gm.html">asc_copy_l0c2gm</a></td><td>将L0C中的数据搬运到GM中。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_store/asc_copy_l0c2gm_arch_2201.html">asc_copy_l0c2gm（NPU架构版本2201）</a></td><td>将L0C Buffer中的矩阵计算结果搬运到GM，支持随路量化处理。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_store/asc_copy_l0c2gm_arch_3510.html">asc_copy_l0c2gm（NPU架构版本3510）</a></td><td>将矩阵计算结果从L0C Buffer搬运至Global Memory，搬运过程中可同步支持随路量化、随路激活、随路格式转换（Nz2ND/Nz2DN）等能力组合。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_store/asc_copy_l0c2l1.html">asc_copy_l0c2l1</a></td><td>矩阵计算完成后，对结果进行量化处理，之后将处理结果搬运到L1中。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_store/asc_copy_l0c2l1_arch_2201.html">asc_copy_l0c2l1（NPU架构版本2201）</a></td><td>将L0C Buffer中的矩阵计算结果搬运到L1 Buffer，支持随路量化处理。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_store/asc_copy_l0c2l1_arch_3510.html">asc_copy_l0c2l1（NPU架构版本3510）</a></td><td>将矩阵计算结果从L0C Buffer搬运到L1 Buffer，支持随路量化、ReLU、Nz2ND格式转换和通道拆分。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_store/asc_copy_l0c2ub.html">asc_copy_l0c2ub</a></td><td>将L0C中的数据搬运到UB中。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_store/asc_copy_l12gm.html">asc_copy_l12gm</a></td><td>将数据从L1搬运到GM。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_compute_store/asc_copy_l12ub.html">asc_copy_l12ub</a></td><td>将数据从L1 Buffer搬运到UB中。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr></tbody></table><h3 id="矩阵搬出辅助配置接口">矩阵搬出辅助配置接口<a class="header-anchor" href="#矩阵搬出辅助配置接口">​</a></h3><p><strong>表4</strong> 矩阵搬出辅助配置接口</p><table><thead><tr><th>接口名称</th><th>接口描述</th><th>最细粒度公共头文件</th></tr></thead><tbody><tr><td><a href="cube_store_aux_config/asc_get_l0c2gm_prequant.html">asc_get_l0c2gm_prequant</a></td><td>数据搬运过程中进行随路量化时，通过调用该接口获取量化操作前矢量的起始地址。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_store_aux_config/asc_get_l0c2gm_relu.html">asc_get_l0c2gm_relu</a></td><td>数据搬运过程中进行随路量化时，通过调用该接口获取ReLU操作前矢量的起始地址。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_store_aux_config/asc_get_l0c2gm_unitflag.html">asc_get_l0c2gm_unitflag</a></td><td>数据搬运过程中进行随路量化时，通过调用该接口获取<code>unit_flag</code>设置。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_store_aux_config/asc_set_l0c_copy_channel_para.html">asc_set_l0c_copy_channel_para</a></td><td>配置Nz2DN格式转换时源Nz矩阵中相邻行的地址偏移。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_store_aux_config/asc_set_l0c_copy_config.html">asc_set_l0c_copy_config</a></td><td>设置L0C Buffer搬出场景下随路tensor量化、随路tensor激活和UnitFlag功能的相关配置。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_store_aux_config/asc_set_l0c_copy_lrelu_alpha.html">asc_set_l0c_copy_lrelu_alpha</a></td><td>在L0C Buffer搬出过程中进行随路Scalar激活时，配置激活计算所需的缩放系数。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_store_aux_config/asc_set_l0c_copy_nz_para.html">asc_set_l0c_copy_nz_para</a></td><td>数据搬运过程中进行随路格式转换（NZ格式转换为ND格式）时，设置格式转换的相关配置。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_store_aux_config/asc_set_l0c_copy_params.html">asc_set_l0c_copy_params</a></td><td>将L0C Buffer数据搬运到Global Memory或L1 Buffer并进行随路格式转换（NZ格式转换为ND格式）时，通过该接口设置格式转换的相关配置。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_store_aux_config/asc_set_l0c_copy_prequant.html">asc_set_l0c_copy_prequant</a></td><td>数据搬运过程中进行随路量化时，通过调用该接口设置量化流程中的标量量化参数。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr><tr><td><a href="cube_store_aux_config/asc_set_l0c_copy_relu_alpha.html">asc_set_l0c_copy_relu_alpha</a></td><td>在L0C Buffer搬出过程中进行随路Scalar激活时，配置激活计算所需的缩放系数。</td><td><code>c_api/cube_datamove/cube_datamove.h</code></td></tr></tbody></table></article></div>',1)])])}const s=a(d,[["render",o]]);export{b as __pageData,s as default};
